import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"20、【觀】 坤下巽上","description":"周易口訣義 - 20、【觀】 坤下巽上","frontmatter":{"title":"20、【觀】 坤下巽上","description":"周易口訣義 - 20、【觀】 坤下巽上"},"headers":[],"relativePath":"classics/koujueyi/022.md","filePath":"classics/koujueyi/022.md"}'),r={name:"classics/koujueyi/022.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_20、【觀】-坤下巽上" tabindex="-1">20、【觀】 坤下巽上 <a class="header-anchor" href="#_20、【觀】-坤下巽上" aria-label="Permalink to “20、【觀】 坤下巽上”">​</a></h1><p>彖曰：大觀在上，順而巽，中正以觀天下。</p><p>「觀盥而不薦，有孚顒若」，下觀而化也。觀天之神道而四時不忒，聖人以神道設教而天下服矣。</p><p>象曰：風行地上，觀。先王以省方觀民設教。</p><p>初六：童觀，小人無咎，君子吝。</p><p>象曰：「初六童觀」，「小人」道也。</p><p>六二：窺觀，利女貞。</p><p>象曰：「窺觀女貞」，亦可醜也。</p><p>六三：觀我生，進退。</p><p>象曰：「觀我生進退」，未失道也。</p><p>六四，觀國之光，利用賓於王。</p><p>象曰：「觀國之光」，尚賓也。</p><p>九五，觀我生，君子無咎。</p><p>象曰：「觀我生」，觀民也。</p><p>上九，觀其生，君子無咎。</p><p>象曰：「觀其生」，志未平也。</p><p>解讀</p><p>「觀盥而不薦」者，觀謂王者道德，民所觀看也；盥謂瓶罍灌洗之器物也，薦謂籩豆陳薦之屬也。今所觀王者施瓶盥之禮，為民祈福，還威儀嚴敬否？故不觀陳薦之物也。「有孚顒若」者，孚，信也，顒是嚴整之貌，謂君子行禮潔信，立誠端敬，顒然若鬼神在，則下觀其德，民順其化，故詩云「顒顒卬卬，如圭如璋」，君德之義也。象曰「風行地上，觀」者，風如王者風教行於地上，人所觀也。「先王省方，觀民設教」者，先王以省視萬方，觀看民俗，施設教化，故鄭眾雲：「從俗所為，順民之教，故君子治人不求變俗」是也。如封太公於齊，五月報政，為簡其君臣禮，從俗不同；伯禽於魯，變其俗，易其禮，三年報政也。</p><p>「初六童觀，小人無咎，君子吝」者，觀之為體，下賤上貴也。最處於下，而不近朝廷之美，所觀𥚹狹，如童稚之見，故云「童觀」也。大觀之時若如是，乃小人之見，才得無咎；君子居之，深可鄙吝也。</p><p>「六二𬮭觀，利女貞」者，居內處中，所見非大，猶𬮭竊而觀望，此乃利女之正，非丈夫之正，處大觀之時，而為𬮭竊觀看，誠可醜也。</p><p>「六三觀我生，進退」者，生，猶道也。六三處下卦之上，是可進之時；居上卦之下，又是可退之地。處此之時，可以觀風相幾而不失其道也。</p><p>「六四觀國之光，利用賓於王」者，處近君之尊，故可觀國之光華矣；習國家之禮儀，故可利為王賓也。</p><p>「九五觀我生，君子無咎」者，居得尊位，為觀之主，四海之內，皆由我化。我化若善，天下習君子之風；我化不善，天下有小人之俗。故我觀之道，有君子之風著，又何有咎也。</p><p>「上六觀其生，君子無咎」者，觀其生則是為人所觀者也，最上處極，為天下所觀於己之道，若能自戒慎，高尚其事，著君子之風，故得「無咎」。王傳雲：「獨處異地，不易執持。」此明上九但卓立其身，異於塵俗，何咎之有？故論語云：「君子之過，如日月之食。過也，人皆見之；更也，人皆仰之。」</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
